/**
 * Write the properties of an instance
 * of {@link types!Something}, and neither the opening
 * nor the closing tag of the element which holds them -- which is the contract of
 * a `ContentWriter`, so this function is used as one.
 */
function writeSomethingAsSequence(
  parts: Array<string>,
  that: AasTypes.Something
): void {
  writeProperty(
    parts,
    "root",
    that.root,
    writeClass
  );
  writeOptionalProperty(
    parts,
    "optionalElement",
    that.optionalElement,
    writeClass
  );
  writeProperty(
    parts,
    "value",
    that.value,
    writeClass
  );
  writeProperty(
    parts,
    "values",
    that.values,
    writeListOfInstances
  );
}

const PARSERS_OF_ELEMENT = new Map<
  string,
  ContentParser<AasTypes.IElement>
>([
  ["leaf", parseLeafFromSequence],
  ["orderedContainer", parseOrderedContainerFromSequence],
  ["unorderedContainer", parseUnorderedContainerFromSequence]
]);

/**
 * Dispatch-parse an instance
 * of {@link types!IElement} from the next
 * XML element in `cursor`, based on the element's local name.
 *
 * @param cursor - to read from
 * @returns the parsed instance, or an error
 */
function dispatchParseElementElement(
  cursor: XmlCursor
): AasCommon.Either<AasTypes.IElement, DeserializationError> {
  return dispatchParseElement(
    cursor,
    "IElement",
    PARSERS_OF_ELEMENT
  );
}

/**
 * Parse an XML string as an instance
 * of {@link types!IElement}.
 *
 * @param xml - XML string to parse
 * @returns parsed instance, or an error
 */
export function elementFromXmlString(
  xml: string
): AasCommon.Either<AasTypes.IElement, DeserializationError> {
  if (xml.length === 0) {
    return newDeserializationError<AasTypes.IElement>(
      "Expected an XML document, but got an empty string"
    );
  }

  const tokensOrError = tokenizeXml(xml);
  if (tokensOrError.error !== null) {
    return new AasCommon.Either<AasTypes.IElement, DeserializationError>(
      null,
      tokensOrError.error
    );
  }

  const cursor = new XmlCursor(tokensOrError.mustValue());

  const instanceOrError = dispatchParseElementElement(cursor);
  if (instanceOrError.error !== null) {
    return instanceOrError;
  }

  cursor.skipIgnorable();
  if (cursor.current() !== null) {
    return newDeserializationError<AasTypes.IElement>(
      "Expected no tokens after the root XML element, but got token kind: " +
        currentTokenKind(cursor)
    );
  }

  return instanceOrError;
}

